data.query:
query(
  $countId: String!,
  $serialNumber: String!
){

  inventory(where:  {
     serialNumber:  {
        _eq: $serialNumber
     }
  }){
    edges{
      node{
        id
        serialNumber
        quantity{ value unitId }
        grossWeight{ value  unitId}
        product{
          id code
        }
        storageUnit{
          id code
        }
        countLineInventories(where:  {
           countLine:  {
              countId:  {
                 _eq: $countId
              }
           }
        }){
          edges{
            node{
              id
              counterUserId
              storageUnit{
                code id
              }
              quantity{ value }
              weight{ value }
              countLine{
                id
                expectedQuantity
                expectedWeight
              }
            }
          }
        }
      }
    }
  }

}

data.transform:
(

  $inventory := inventory.edges.node;
  $countLineId := $join([$metadata.querystring.countId, $inventory.product.id, $inventory.storageUnit.id], "::");

  {
    "countLineInventoryPayload": [
      {
        "create":{
          "countLineId": $countLineId,
          "inventoryId": $inventory.id,
          "quantity": $inventory.quantity,
          "storageUnitId": $components.Form2.data.storageUnit.id,
          "weight": $inventory.grossWeight,
          "note": "This inventory was added to the count after it had already been started"

        }
      }
    ],
    "countLinePayload": [
      {
        "where":{"id":$countLineId },
        "create":{
          "expectedQuantity": 0,
          "expectedWeight": 0,
          "expectedStorageUnitId": $inventory.storageUnit.id,
          "productId":  $inventory.product.id,
          "countId": $metadata.querystring.countId
        },
        "update":{}
      }
    ]
  }
)

